class Solution {
    public int maximalRectangle(char[][] matrix) {
        int rows = matrix.length;
        int cols = matrix[0].length;
        int[] heights = new int[cols];
        int best = 0;

        for (int row = 0; row < rows; row++) {
            for (int col = 0; col < cols; col++) {
                heights[col] = matrix[row][col] == '1' ? heights[col] + 1 : 0;
            }
            best = Math.max(best, largestRectangleArea(heights));
        }
        return best;
    }

    private int largestRectangleArea(int[] heights) {
        java.util.Deque<Integer> stack = new java.util.ArrayDeque<>();
        int best = 0;
        for (int index = 0; index <= heights.length; index++) {
            int currentHeight = index == heights.length ? 0 : heights[index];
            while (!stack.isEmpty() && currentHeight < heights[stack.peek()]) {
                int height = heights[stack.pop()];
                int leftBoundary = stack.isEmpty() ? -1 : stack.peek();
                int width = index - leftBoundary - 1;
                best = Math.max(best, height * width);
            }
            stack.push(index);
        }
        return best;
    }
}

class Solution {
    public int maximalRectangle(char[][] matrix) {
        int rows = matrix.length;
        int cols = matrix[0].length;
        int[] height = new int[cols];
        int[] left = new int[cols];
        int[] right = new int[cols];
        java.util.Arrays.fill(right, cols);
        int best = 0;

        for (int row = 0; row < rows; row++) {
            int currentLeft = 0;
            for (int col = 0; col < cols; col++) {
                if (matrix[row][col] == '1') {
                    height[col]++;
                    left[col] = Math.max(left[col], currentLeft);
                } else {
                    height[col] = 0;
                    left[col] = 0;
                    right[col] = cols;
                    currentLeft = col + 1;
                }
            }

            int currentRight = cols;
            for (int col = cols - 1; col >= 0; col--) {
                if (matrix[row][col] == '1') {
                    right[col] = Math.min(right[col], currentRight);
                } else {
                    right[col] = cols;
                    currentRight = col;
                }
            }

            for (int col = 0; col < cols; col++) {
                best = Math.max(best, height[col] * (right[col] - left[col]));
            }
        }
        return best;
    }
}

class Solution {
    public int maximalRectangle(char[][] matrix) {
        int rows = matrix.length;
        int cols = matrix[0].length;
        int[][] width = new int[rows][cols];
        int best = 0;

        for (int row = 0; row < rows; row++) {
            for (int col = 0; col < cols; col++) {
                if (matrix[row][col] == '1') {
                    width[row][col] = (col == 0 ? 0 : width[row][col - 1]) + 1;
                    int minWidth = width[row][col];
                    for (int top = row; top >= 0 && width[top][col] > 0; top--) {
                        minWidth = Math.min(minWidth, width[top][col]);
                        int height = row - top + 1;
                        best = Math.max(best, minWidth * height);
                    }
                }
            }
        }
        return best;
    }
}

class Solution {
    public int maximalRectangle(char[][] matrix) {
        int rows = matrix.length;
        int cols = matrix[0].length;
        int best = 0;

        for (int left = 0; left < cols; left++) {
            boolean[] rowAllOnes = new boolean[rows];
            java.util.Arrays.fill(rowAllOnes, true);
            for (int right = left; right < cols; right++) {
                int consecutiveRows = 0;
                for (int row = 0; row < rows; row++) {
                    rowAllOnes[row] = rowAllOnes[row] && matrix[row][right] == '1';
                    if (rowAllOnes[row]) {
                        consecutiveRows++;
                        best = Math.max(best, consecutiveRows * (right - left + 1));
                    } else {
                        consecutiveRows = 0;
                    }
                }
            }
        }
        return best;
    }
}
